/**
 * [P4-2] topic_classifier.ts — HR policy scope gate
 *
 * Classifies an incoming query as:
 *   hr_policy  — in scope for the AI policy assistant
 *   off_topic  — out of scope; return a fixed professional rejection
 *   borderline — ambiguous; return a clarification prompt, not a rejection
 *
 * Uses Claude Haiku at temperature=0 for speed (< 100ms target).
 * Output is structured JSON parsed from the model response.
 * Rejection and clarification messages are hardcoded constants —
 * NEVER generated by the LLM to prevent prompt injection / manipulation.
 *
 * All classifications are logged with a hashed query (SHA-256 truncated to
 * 8 hex chars) — never the raw query — for privacy.
 */

import { logger } from '../../src/lib/logger';

// ---------------------------------------------------------------------------
// Public constants — fixed strings, never LLM-generated
// ---------------------------------------------------------------------------

export const REJECTION_MSG =
  "I can only answer questions about your relocation policy and associated benefits. " +
  "For other matters, please contact your HR Business Partner directly.";

export const CLARIFICATION_TEMPLATE =
  "I can tell you what your relocation policy says about [topic]. Is that what you're looking for?";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type TopicCategory = 'hr_policy' | 'off_topic' | 'borderline';

export type FallbackReason = 'TOPIC_REJECTED' | 'LOW_CONFIDENCE' | 'FAITHFULNESS_FAIL' | 'POLICY_EXPIRED';

export interface ClassificationResult {
  category: TopicCategory;
  /** Confidence score 0–1 from the model */
  confidence: number;
  /** Only set when category === 'off_topic' — always the hardcoded REJECTION_MSG */
  rejection_reason?: string;
  /** Only set when category === 'borderline' — clarification prompt for the user */
  clarification_prompt?: string;
  /** SHA-256 truncated hash of the query (8 hex chars) — for logging only */
  query_hash: string;
  /** Latency in milliseconds */
  latency_ms: number;
}

interface AnthropicMessage {
  role: 'user' | 'assistant';
  content: string;
}

// ---------------------------------------------------------------------------
// Few-shot examples (10 per category as per spec)
// ---------------------------------------------------------------------------

const FEW_SHOT_EXAMPLES: Array<{ query: string; category: TopicCategory; reason: string }> = [
  // hr_policy (10)
  { query: "What is the housing allowance for a Manager moving to Norway?", category: "hr_policy", reason: "Direct policy entitlement question" },
  { query: "How much relocation lump sum do Senior employees receive?", category: "hr_policy", reason: "Benefit amount inquiry" },
  { query: "Are schooling costs covered for my children during assignment?", category: "hr_policy", reason: "Dependent benefit question" },
  { query: "When does my housing allowance start after I arrive?", category: "hr_policy", reason: "Policy timing / procedure" },
  { query: "Is the relocation lump sum taxable in Norway?", category: "hr_policy", reason: "Tax treatment of a policy benefit" },
  { query: "What forms do I need to submit for the housing reimbursement?", category: "hr_policy", reason: "Policy procedure / forms" },
  { query: "Can I get an advance on my relocation payment?", category: "hr_policy", reason: "Benefit administration question" },
  { query: "What is the maximum schooling allowance per child per year?", category: "hr_policy", reason: "Cap / limit on a policy benefit" },
  { query: "Does the policy cover pet transport costs?", category: "hr_policy", reason: "Scope of relocation coverage" },
  { query: "How many business class flights am I entitled to for home visits?", category: "hr_policy", reason: "Travel benefit entitlement" },

  // off_topic (10)
  { query: "What's the weather like in Oslo in January?", category: "off_topic", reason: "General knowledge, not policy" },
  { query: "Can you help me write a Python script to parse a CSV?", category: "off_topic", reason: "Technical coding request" },
  { query: "Who won the Champions League last season?", category: "off_topic", reason: "Sports / general news" },
  { query: "What's a good restaurant near the Oslo opera house?", category: "off_topic", reason: "Local recommendations, not HR" },
  { query: "Can you translate this document from Norwegian to English?", category: "off_topic", reason: "Translation service, not policy" },
  { query: "What are the best practices for React state management?", category: "off_topic", reason: "Software engineering, not HR policy" },
  { query: "I'm feeling stressed about the move, any tips?", category: "off_topic", reason: "Personal wellbeing, not policy" },
  { query: "What is the capital of France?", category: "off_topic", reason: "General knowledge" },
  { query: "Can you summarise the latest GDPR changes?", category: "off_topic", reason: "Legal / regulatory, not relocation policy" },
  { query: "What HR software does our company use?", category: "off_topic", reason: "IT systems, not relocation entitlement" },

  // borderline (5 — enough to illustrate the pattern)
  { query: "Can I work from home after the relocation?", category: "borderline", reason: "May relate to remote work provisions in policy, needs clarification" },
  { query: "What happens if I decide not to complete the assignment?", category: "borderline", reason: "Could be about clawback / early termination provisions" },
  { query: "Do I need a lawyer for the immigration paperwork?", category: "borderline", reason: "Immigration support may be covered by policy" },
  { query: "How long does the process take?", category: "borderline", reason: "Ambiguous — timelines for what? May relate to policy procedures" },
  { query: "Who should I contact for help?", category: "borderline", reason: "Could be a policy question about the support structure" },
];

// ---------------------------------------------------------------------------
// Prompt builder
// ---------------------------------------------------------------------------

function buildClassificationPrompt(query: string): string {
  const examplesJson = FEW_SHOT_EXAMPLES.map(
    (e) => `{"query": ${JSON.stringify(e.query)}, "category": "${e.category}", "reason": "${e.reason}"}`,
  ).join('\n');

  return `You are a topic classifier for a HR relocation policy AI assistant.
Your job is to classify whether a user query is within scope for the assistant.

CATEGORIES:
- "hr_policy": Questions about relocation benefits, allowances, entitlements, policy rules, procedures, immigration support, or related topics that appear in a corporate relocation policy.
- "off_topic": Questions about anything unrelated to HR relocation policy — weather, coding, sports, restaurants, general knowledge, personal advice, etc.
- "borderline": Queries that MIGHT relate to relocation policy but are ambiguous and need clarification before answering.

EXAMPLES (one JSON object per line):
${examplesJson}

Now classify the following query. Reply with ONLY a JSON object on a single line, no markdown, no explanation:
{"category": "<hr_policy|off_topic|borderline>", "confidence": <0.0-1.0>, "detected_topic": "<short phrase describing what the query is about>"}

Query: ${JSON.stringify(query)}`;
}

// ---------------------------------------------------------------------------
// Query hashing (privacy — never log raw queries)
// ---------------------------------------------------------------------------

async function hashQuery(query: string): Promise<string> {
  try {
    // Web Crypto API (browser + Deno)
    const encoder = new TextEncoder();
    const data = encoder.encode(query.toLowerCase().trim());
    const hashBuffer = await crypto.subtle.digest('SHA-256', data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map((b) => b.toString(16).padStart(2, '0')).join('').slice(0, 8);
  } catch {
    // Fallback: simple deterministic string hash (Node without webcrypto)
    let h = 0x811c9dc5;
    for (let i = 0; i < query.length; i++) {
      h ^= query.charCodeAt(i);
      h = (h * 0x01000193) >>> 0;
    }
    return h.toString(16).padStart(8, '0');
  }
}

// ---------------------------------------------------------------------------
// Core classifier
// ---------------------------------------------------------------------------

/**
 * Classify a query against the HR policy scope gate.
 *
 * @param query         The raw user query string
 * @param anthropicKey  Anthropic API key (injected for testability)
 * @param apiBase       API base URL (override for tests)
 */
export async function classify(
  query: string,
  anthropicKey?: string,
  apiBase = 'https://api.anthropic.com',
): Promise<ClassificationResult> {
  const t0 = Date.now();
  const query_hash = await hashQuery(query);

  if (!query.trim()) {
    return {
      category: 'off_topic',
      confidence: 1.0,
      rejection_reason: REJECTION_MSG,
      query_hash,
      latency_ms: Date.now() - t0,
    };
  }

  const apiKey = anthropicKey ?? (typeof import.meta !== 'undefined'
    ? (import.meta.env?.VITE_ANTHROPIC_API_KEY as string | undefined)
    : process.env.ANTHROPIC_API_KEY);

  if (!apiKey) {
    throw new Error('topic_classifier: ANTHROPIC_API_KEY is not configured');
  }

  const messages: AnthropicMessage[] = [
    { role: 'user', content: buildClassificationPrompt(query) },
  ];

  const response = await fetch(`${apiBase}/v1/messages`, {
    method: 'POST',
    headers: {
      'x-api-key': apiKey,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json',
    },
    body: JSON.stringify({
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 100,
      temperature: 0,
      messages,
    }),
  });

  if (!response.ok) {
    const body = await response.text().catch(() => '');
    throw new Error(`topic_classifier: API error ${response.status}: ${body}`);
  }

  const apiResponse = (await response.json()) as {
    content: Array<{ type: string; text: string }>;
  };

  const rawText = apiResponse.content.find((c) => c.type === 'text')?.text?.trim() ?? '';

  // Parse structured JSON from model output
  let parsed: { category: TopicCategory; confidence: number; detected_topic?: string };
  try {
    // Strip any accidental markdown fencing
    const cleaned = rawText.replace(/```json|```/g, '').trim();
    parsed = JSON.parse(cleaned) as { category: TopicCategory; confidence: number; detected_topic?: string };
  } catch {
    // If parsing fails, default to borderline (safe fallback — triggers clarification)
    logger.warn(`[topic_classifier] JSON parse failed for hash=${query_hash}, raw="${rawText.slice(0, 100)}"`);
    parsed = { category: 'borderline', confidence: 0.5 };
  }

  // Validate category
  const validCategories: TopicCategory[] = ['hr_policy', 'off_topic', 'borderline'];
  const category: TopicCategory = validCategories.includes(parsed.category)
    ? parsed.category
    : 'borderline';

  const confidence = typeof parsed.confidence === 'number'
    ? Math.max(0, Math.min(1, parsed.confidence))
    : 0.5;

  const latency_ms = Date.now() - t0;

  // Log (never the raw query — only the hash and category)
  logger.log(
    `[topic_classifier] hash=${query_hash} category=${category} confidence=${confidence.toFixed(2)} latency=${latency_ms}ms`,
  );

  const result: ClassificationResult = { category, confidence, query_hash, latency_ms };

  if (category === 'off_topic') {
    // Always the hardcoded constant — never LLM-generated
    result.rejection_reason = REJECTION_MSG;
  } else if (category === 'borderline') {
    const detectedTopic = parsed.detected_topic ?? 'this topic';
    result.clarification_prompt = CLARIFICATION_TEMPLATE.replace('[topic]', detectedTopic);
  }

  return result;
}

// ---------------------------------------------------------------------------
// Pure rule-based fast-path (no LLM call) for obviously off-topic queries
// ---------------------------------------------------------------------------

/**
 * Heuristic pre-filter that catches obviously off-topic queries without an API
 * call. Returns null if the query is not obviously off-topic (pass to LLM).
 *
 * This is NOT the primary classifier — it's a latency optimisation for the
 * most blatant off-topic queries to avoid any API round-trip.
 */
export function fastPathReject(query: string): ClassificationResult | null {
  const lower = query.toLowerCase().trim();

  // Patterns that are unambiguously off-topic
  const offTopicPatterns = [
    /^(what('s| is) the weather|weather in|forecast for)/,
    /\b(recipe|cook|restaurant|cafe|bar|food near)\b/,
    /\b(python|javascript|typescript|react|sql|code|script|function|algorithm)\b/,
    /\b(who won|champions league|football|soccer|basketball|sport)\b/,
    /\b(translate|translation|in german|in french|auf deutsch)\b/,
    /^(hi|hello|hey|good morning|good afternoon)[\s!.]*$/,
  ];

  const matched = offTopicPatterns.some((p) => p.test(lower));
  if (!matched) return null;

  return {
    category: 'off_topic',
    confidence: 0.99,
    rejection_reason: REJECTION_MSG,
    query_hash: 'fast-path',
    latency_ms: 0,
  };
}

// ---------------------------------------------------------------------------
// Main entry point with fast-path optimisation
// ---------------------------------------------------------------------------

/**
 * Classify a query, using the rule-based fast-path for obvious rejections
 * and the LLM classifier for everything else.
 */
export async function classifyQuery(
  query: string,
  anthropicKey?: string,
): Promise<ClassificationResult> {
  // Fast-path: skip LLM for obviously off-topic queries
  const fastResult = fastPathReject(query);
  if (fastResult) return fastResult;

  return classify(query, anthropicKey);
}
